var FloorplanStore=(()=>{let pending;function db(){return pending||=new Promise((resolve,reject)=>{const r=indexedDB.open('immobrain-floorplans-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result)};r.onerror=()=>{pending=null;reject(Error('Lokaler Bildspeicher nicht verfügbar.'))}})}async function run(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('projects',mode);const r=fn(tx.objectStore('projects'));tx.oncomplete=()=>resolve(r.result);tx.onerror=tx.onabort=()=>reject(Error('Speichern fehlgeschlagen. Bitte Bild herunterladen und Browserspeicher prüfen.'))})}return {all:()=>run('readonly',s=>s.getAll()),get:id=>run('readonly',s=>s.get(id)),put:p=>run('readwrite',s=>s.put(p)),remove:id=>run('readwrite',s=>s.delete(id))}})();
